#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 9260 §3.3.7 heartbeat chunk (type 4) on ports 1234 -> 5678, tag 0x11223344.
    fn vector() -> Vec<u8> {
        vec![
            0x04, 0xd2, 0x16, 0x2e, 0x11, 0x22, 0x33, 0x44, 0x00, 0x00, 0x00, 0x00, 0x04, 0x00,
            0x00, 0x08, 0x00, 0x01, 0x00, 0x04,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Sctp);
        let l = p.find_layer(ProtoId::Sctp).unwrap();
        assert_eq!(p.get(l, "sport").unwrap(), FieldValue::Uint(1234));
        assert_eq!(p.get(l, "dport").unwrap(), FieldValue::Uint(5678));
        assert_eq!(p.get(l, "tag").unwrap(), FieldValue::Uint(287454020));
        assert_eq!(p.get(l, "chksum").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Sctp);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Sctp);
        let l = p.find_layer(ProtoId::Sctp).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Sctp, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
